import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"動的文字列","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/enums/dynamic-strings.md","filePath":"ja/language/enums/dynamic-strings.md"}'),n={name:"ja/language/enums/dynamic-strings.md"};function l(d,e,c,r,g,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="動的文字列" tabindex="-1">動的文字列 <a class="header-anchor" href="#動的文字列" aria-label="Permalink to &quot;動的文字列&quot;">​</a></h1><p>実行時の置換を伴うテキスト表示アクション用のオペランド型です。ManagedMegalo 文法では <code>&lt;dynamic_string&gt;</code> として現れます。ワイヤ上では <code>c_dynamic_string</code> — 文字列テーブルのインデックスと、最大 2 個の置換可能トークン — として格納されます。</p><p>動的文字列は常に <a href="/MegaloEvolved/beta/docs/ja/language/elements/string-table">文字列テーブル</a> シンボル、または <a href="/MegaloEvolved/beta/docs/ja/language/syntax#string-table-symbols-vs-inline-literals">インラインリテラル</a> で、続けてそのテキスト内の <code>%</code> プレースホルダを埋める参照オペランドを 0〜2 個取ります。</p><h2 id="プレースホルダ" tabindex="-1">プレースホルダ <a class="header-anchor" href="#プレースホルダ" aria-label="Permalink to &quot;プレースホルダ&quot;">​</a></h2><p>文字列を左から右へ走査し、<code>%</code> の直後に既知の文字がある箇所を探します。各マッチは文字列の次のアクションオペランドを消費します。プレースホルダは最大 <strong>2</strong> 個までです。3 個目はコンパイルエラー（<code>Too many replacement tokens!</code>）になります。未知の <code>%X</code> 列は無視され、オペランドを消費しません。</p><table tabindex="0"><thead><tr><th>指定子</th><th>オペランド型</th><th>オペランド例</th></tr></thead><tbody><tr><td><code>%n</code></td><td><a href="/MegaloEvolved/beta/docs/ja/language/references#reference-types">数値</a>（カスタム変数）</td><td><code>score_to_win_round</code>、<code>1</code>、<code>global.my_counter</code></td></tr><tr><td><code>%p</code></td><td><a href="/MegaloEvolved/beta/docs/ja/language/references#reference-types">プレイヤー</a></td><td><code>current_player</code>、<code>killing_player</code></td></tr><tr><td><code>%t</code></td><td><a href="/MegaloEvolved/beta/docs/ja/language/references#team-designators">チーム</a></td><td><code>attackers</code>、<code>current_player.team</code></td></tr><tr><td><code>%o</code></td><td><a href="/MegaloEvolved/beta/docs/ja/language/references#reference-types">オブジェクト</a></td><td><code>current_object</code>、<code>global.flag</code></td></tr><tr><td><code>%s</code></td><td><a href="/MegaloEvolved/beta/docs/ja/language/references#reference-types">タイマー</a></td><td><code>global.round_timer</code>、<code>sudden_death_timer</code></td></tr></tbody></table><p><code>%s</code> は（C の <code>printf</code> とは異なり）<strong>文字列ではありません</strong>。タイマーを挿入します — <code>%t</code> が既にチームを意味するため、おそらく「<strong>s</strong>econds」です。エンジンはタイマーの残り時間をそのスロットに整形して入れます。</p><p>オペランドの順序は、上表の文字順ではなく、文字列内のプレースホルダの出現順に一致します。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action player_set_objective current_player </span><span class="megalo-string">&quot;+</span><span class="megalo-regexp">%n</span><span class="megalo-string">&quot;</span><span class="megalo-text"> score_to_win_round</span></span>
<span class="line"><span class="megalo-text">action hud_post_message everyone none </span><span class="megalo-string">&quot;</span><span class="megalo-regexp">%p</span><span class="megalo-string"> scored!&quot;</span><span class="megalo-text"> scoring_player</span></span>
<span class="line"><span class="megalo-text">action navpoint_set_text current_object </span><span class="megalo-string">&quot;</span><span class="megalo-regexp">%n</span><span class="megalo-string"> s&quot;</span><span class="megalo-text"> global</span><span class="megalo-operator">.</span><span class="megalo-text">countdown</span></span></code></pre></div><p>実行時、エンジンは各トークンを対応する <code>%</code> スロットに置換します（例: <code>&quot;+%n&quot;</code> と <code>score_to_win_round</code> → <code>+25</code>）。</p><h2 id="永続と一時" tabindex="-1">永続と一時 <a class="header-anchor" href="#永続と一時" aria-label="Permalink to &quot;永続と一時&quot;">​</a></h2><p>一部のアクションは動的文字列を <strong>永続（persistent）</strong> として扱います — トリガー終了後もテキストが有効である必要があります。そうしたアクションは、トークンオペランド内の <strong>一時（transient）</strong> 変数参照を拒否します（<code>Can&#39;t use transient variables when reading a persistent string</code>）。</p><table tabindex="0"><thead><tr><th>モード</th><th>アクション</th><th>一時トークン</th></tr></thead><tbody><tr><td>永続</td><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/hud-widget-set-text"><code>hud_widget_set_text</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/hud-widget-set-value"><code>hud_widget_set_value</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/navpoint-set-text"><code>navpoint_set_text</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/player-set-objective"><code>player_set_objective</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/player-set-objective-allegiance"><code>player_set_objective_allegiance</code></a></td><td>禁止</td></tr><tr><td>一時</td><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/hud-post-message"><code>hud_post_message</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/print-variable"><code>print_variable</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/saved-film-insert-marker"><code>saved_film_insert_marker</code></a></td><td>許可</td></tr></tbody></table><h2 id="使用箇所" tabindex="-1">使用箇所 <a class="header-anchor" href="#使用箇所" aria-label="Permalink to &quot;使用箇所&quot;">​</a></h2><table tabindex="0"><thead><tr><th>アクション</th><th>文法</th></tr></thead><tbody><tr><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/hud-post-message"><code>hud_post_message</code></a></td><td><code>&lt;team_or_player_target&gt; &lt;sound&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/print-variable"><code>print_variable</code></a></td><td><code>&lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/hud-widget-set-text"><code>hud_widget_set_text</code></a></td><td><code>&lt;hud_widget_name&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/hud-widget-set-value"><code>hud_widget_set_value</code></a></td><td><code>&lt;hud_widget_name&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/navpoint-set-text"><code>navpoint_set_text</code></a></td><td><code>&lt;object&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/player-set-objective"><code>player_set_objective</code></a></td><td><code>&lt;player&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/player-set-objective-allegiance"><code>player_set_objective_allegiance</code></a></td><td><code>&lt;player&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/ja/language/actions/saved-film-insert-marker"><code>saved_film_insert_marker</code></a></td><td><code>&lt;offset (s)&gt; &lt;label&gt;</code> — <code>&lt;label&gt;</code> は動的文字列としてパースされる</td></tr></tbody></table><h2 id="ローカライズ" tabindex="-1">ローカライズ <a class="header-anchor" href="#ローカライズ" aria-label="Permalink to &quot;ローカライズ&quot;">​</a></h2><p>文字列が文字列テーブルのシンボルの場合、すべての言語翻訳は <strong>同じ</strong> プレースホルダ型を <strong>同じ</strong> 順序で宣言する必要があります。言語間で <code>%</code> トークンが不一致だとコンパイルエラーになります。出荷テキストにはインラインリテラルよりシンボルを推奨します — <a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings#string-literal-strictness">文字列リテラルの厳格さ</a> を参照してください。</p><h2 id="例" tabindex="-1">例 <a class="header-anchor" href="#例" aria-label="Permalink to &quot;例&quot;">​</a></h2><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">string_table</span><span class="megalo-text"> </span><span class="megalo-enumMember">english</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-variable">obj_score</span><span class="megalo-text"> </span><span class="megalo-string">&quot;+</span><span class="megalo-regexp">%n</span><span class="megalo-string">&quot;</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-variable">msg_scored</span><span class="megalo-text"> </span><span class="megalo-string">&quot;</span><span class="megalo-regexp">%p</span><span class="megalo-string"> scored!&quot;</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> player_scored</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">player_set_objective</span><span class="megalo-text"> current_player </span><span class="megalo-variable">obj_score</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">hud_post_message</span><span class="megalo-text"> </span><span class="megalo-enumMember">everyone</span><span class="megalo-text"> </span><span class="megalo-variable">none</span><span class="megalo-text"> </span><span class="megalo-variable">msg_scored</span><span class="megalo-text"> scoring_player</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/syntax#format-placeholders">構文 — フォーマットプレースホルダ</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/string-table">文字列テーブル</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/references">参照</a></li></ul>`,21)])])}const _=a(n,[["render",l]]);export{m as __pageData,_ as default};
